import AppKit
import CryptoKit
import Foundation
import Security

/// Signed auto-update checker for TapCopy.
///
/// Flow: GET https://tapcopy.iareal.net/api/updates/latest (no-cache) → monotonic
/// version/build comparison → download the DMG to a temporary folder → verify the
/// Ed25519 signature of the manifest generated by the license authority → verify the
/// SHA-256 of the file byte by byte → only then mount it for the user.
final class AppUpdateChecker {

    static let shared = AppUpdateChecker()

    private static let manifestURL = URL(string: "https://tapcopy.iareal.net/api/updates/latest")!
    private let lastCheckKey = "tapCopyLastUpdateCheck"

    private(set) var isChecking = false

    struct Manifest {
        let version: String
        let build: Int
        let url: URL
        let sha256: String
        let publishedAt: String
        let minimumSystemVersion: String
        let signature: String
    }

    // MARK: - Public API

    /// Silent check on launch: at most once per 24 hours, never interrupts the user.
    func checkSilentlyIfDue() {
        let defaults = UserDefaults.standard
        let last = defaults.object(forKey: lastCheckKey) as? Date ?? .distantPast
        guard Date().timeIntervalSince(last) > 86_400 else { return }
        defaults.set(Date(), forKey: lastCheckKey)
        fetchManifest { [weak self] manifest in
            guard let self, let manifest, self.isNewer(manifest) else { return }
            DispatchQueue.main.async { self.prompt(manifest, silent: true) }
        }
    }

    /// Explicit "Check for Updates…" action: always reports the outcome.
    func checkInteractively() {
        guard !isChecking else { return }
        isChecking = true
        fetchManifest { [weak self] manifest in
            guard let self else { return }
            self.isChecking = false
            DispatchQueue.main.async {
                guard let manifest else {
                    self.alert(
                        title: "No pudimos comprobar actualizaciones",
                        message: "Revisa tu conexión e inténtalo de nuevo.",
                        style: .warning
                    )
                    return
                }
                if self.isNewer(manifest) {
                    self.prompt(manifest, silent: false)
                } else {
                    let local = LicenseManager.localVersion
                    self.alert(
                        title: "TapCopy está al día",
                        message: "Tienes la versión \(local.version) (build \(local.build)).",
                        style: .informational
                    )
                }
            }
        }
    }

    // MARK: - Manifest

    private func fetchManifest(completion: @escaping (Manifest?) -> Void) {
        var request = URLRequest(url: Self.manifestURL)
        request.timeoutInterval = 15
        request.cachePolicy = .reloadIgnoringLocalCacheData
        request.setValue("no-cache", forHTTPHeaderField: "Cache-Control")

        URLSession.shared.dataTask(with: request) { data, response, _ in
            guard let http = response as? HTTPURLResponse, http.statusCode == 200, let data,
                  let json = (try? JSONSerialization.jsonObject(with: data)) as? [String: Any],
                  let version = json["version"] as? String,
                  let build = json["build"] as? Int,
                  let urlString = json["url"] as? String,
                  let url = URL(string: urlString),
                  let sha = json["sha256"] as? String,
                  let signature = json["edSignature"] as? String else {
                completion(nil)
                return
            }
            completion(
                Manifest(
                    version: version,
                    build: build,
                    url: url,
                    sha256: sha.lowercased(),
                    publishedAt: json["publishedAt"] as? String ?? "",
                    minimumSystemVersion: json["minimumSystemVersion"] as? String ?? "14.0",
                    signature: signature
                )
            )
        }.resume()
    }

    private func isNewer(_ manifest: Manifest) -> Bool {
        let local = LicenseManager.localVersion
        if Self.compare(manifest.version, local.version) > 0 { return true }
        if Self.compare(manifest.version, local.version) == 0 { return manifest.build > local.build }
        return false
    }

    /// Numeric dotted-version comparison: 1.1.0 > 1.0.3, 1.10.0 > 1.9.9.
    static func compare(_ lhs: String, _ rhs: String) -> Int {
        let a = lhs.split(separator: ".").map { Int($0) ?? 0 }
        let b = rhs.split(separator: ".").map { Int($0) ?? 0 }
        for index in 0..<max(a.count, b.count) {
            let left = index < a.count ? a[index] : 0
            let right = index < b.count ? b[index] : 0
            if left != right { return left > right ? 1 : -1 }
        }
        return 0
    }

    // MARK: - Signature + checksum

    /// The manifest signature covers `version|build|sha256|url` exactly.
    static func manifestPayload(_ manifest: Manifest) -> String {
        "\(manifest.version)|\(manifest.build)|\(manifest.sha256)|\(manifest.url.absoluteString)"
    }

    /// Apple code-signature gate for the downloaded DMG (Team YH6W55MP95).
    static func verifyAppleSignature(of file: URL) -> Bool {
        var staticCode: SecStaticCode?
        guard SecStaticCodeCreateWithPath(file as CFURL, [], &staticCode) == errSecSuccess,
              let staticCode else {
            return false
        }
        var requirement: SecRequirement?
        let requirementString = "anchor apple generic and certificate leaf[subject.OU] = \"YH6W55MP95\"" as CFString
        guard SecRequirementCreateWithString(requirementString, [], &requirement) == errSecSuccess,
              let requirement else {
            return false
        }
        return SecStaticCodeCheckValidity(staticCode, SecCSFlags(rawValue: kSecCSCheckAllArchitectures), requirement) == errSecSuccess
    }

    static func verifySignature(_ manifest: Manifest) -> Bool {
        guard let publicData = Data(base64Encoded: LicenseManager.publicKeyBase64),
              let publicKey = try? Curve25519.Signing.PublicKey(rawRepresentation: publicData),
              let signature = Data(base64Encoded: manifest.signature) else {
            return false
        }
        return publicKey.isValidSignature(signature, for: Data(manifestPayload(manifest).utf8))
    }

    private static func sha256(of file: URL) -> String? {
        guard let handle = try? FileHandle(forReadingFrom: file) else { return nil }
        defer { try? handle.close() }
        var hasher = SHA256()
        while autoreleasepool(invoking: {
            let chunk = try? handle.read(upToCount: 1 << 20)
            guard let chunk, !chunk.isEmpty else { return false }
            hasher.update(data: chunk)
            return true
        }) {}
        return hasher.finalize().map { String(format: "%02x", $0) }.joined()
    }

    // MARK: - Prompt + download

    private func prompt(_ manifest: Manifest, silent: Bool) {
        let local = LicenseManager.localVersion
        let alert = NSAlert()
        alert.messageText = "TapCopy \(manifest.version) está disponible"
        alert.informativeText = """
        Tienes la versión \(local.version) (build \(local.build)). La nueva compilación \(manifest.version) (build \(manifest.build)) está firmada y notarizada.
        """
        alert.alertStyle = .informational
        alert.addButton(withTitle: "Descargar")
        alert.addButton(withTitle: "Ahora no")
        guard alert.runModal() == .alertFirstButtonReturn else { return }

        guard Self.verifySignature(manifest) else {
            self.alert(
                title: "Actualización no verificada",
                message: "La firma del manifiesto no es válida. No se descargará nada.",
                style: .critical
            )
            return
        }

        download(manifest)
    }

    private func download(_ manifest: Manifest) {
        let target = FileManager.default.temporaryDirectory
            .appendingPathComponent("TapCopy-\(manifest.version).dmg")
        try? FileManager.default.removeItem(at: target)

        let task = URLSession.shared.downloadTask(with: manifest.url) { [weak self] location, response, error in
            guard let self else { return }
            DispatchQueue.main.async {
                guard error == nil,
                      let http = response as? HTTPURLResponse, http.statusCode == 200,
                      let location else {
                    self.alert(
                        title: "Descarga fallida",
                        message: "No pudimos descargar la actualización. Inténtalo más tarde.",
                        style: .warning
                    )
                    return
                }
                do {
                    try FileManager.default.moveItem(at: location, to: target)
                } catch {
                    self.alert(title: "Descarga fallida", message: error.localizedDescription, style: .warning)
                    return
                }

                guard let digest = Self.sha256(of: target), digest == manifest.sha256 else {
                    try? FileManager.default.removeItem(at: target)
                    self.alert(
                        title: "Archivo dañado",
                        message: "El SHA-256 no coincide con el manifiesto firmado. La actualización se descartó.",
                        style: .critical
                    )
                    return
                }

                guard Self.verifyAppleSignature(of: target) else {
                    try? FileManager.default.removeItem(at: target)
                    self.alert(
                        title: "Firma de instalador no válida",
                        message: "El .dmg no está firmado por el equipo oficial YH6W55MP95. La actualización se descartó.",
                        style: .critical
                    )
                    return
                }

                NSWorkspace.shared.open(target)
            }
        }
        task.resume()

        let progress = NSAlert()
        progress.messageText = "Descargando TapCopy \(manifest.version)…"
        progress.informativeText = "El archivo se verificará con SHA-256 y la firma Ed25519 antes de abrirse."
        progress.addButton(withTitle: "Continuar en segundo plano")
        progress.runModal()
    }

    private func alert(title: String, message: String, style: NSAlert.Style) {
        let alert = NSAlert()
        alert.messageText = title
        alert.informativeText = message
        alert.alertStyle = style
        alert.addButton(withTitle: "OK")
        alert.runModal()
    }
}
